def round_robin_merge_three_rankings(list1, list2, list3):
    result = []
    seen = set()
    lists = [list1, list2, list3]
    pointers = [0, 0, 0]
    lengths = [len(l) for l in lists]
    while any(pointers[k] < lengths[k] for k in range(3)):
        for k in range(3):
            if pointers[k] < lengths[k]:
                item = lists[k][pointers[k]]
                pointers[k] += 1
                if item not in seen:
                    seen.add(item)
                    result.append(item)
    return result

def percentile_of_value_among_duplicates(scores, value):
    n = len(scores)
    less = sum(1 for s in scores if s < value)
    equal = sum(1 for s in scores if s == value)
    percentile = (less + equal / 2) / n * 100
    return round(percentile, 2)

def reorder_by_priority_groups(items, category_of, priority):
    groups = {cat: [] for cat in priority}
    others = []
    for item in items:
        cat = category_of[item]
        if cat in groups:
            groups[cat].append(item)
        else:
            others.append(item)
    result = []
    for cat in priority:
        result.extend(groups[cat])
    result.extend(others)
    return result

def sort_indices_by_distance_from_target(nums, target):
    indices = list(range(len(nums)))
    return sorted(indices, key=lambda i: (abs(nums[i] - target), i))

def sort_by_manhattan_distance_from_point(points, target):
    tx, ty = target

    def key(p):
        x, y = p
        return (abs(x - tx) + abs(y - ty), x, y)

    return sorted(points, key=key)

def sort_by_priority_then_recency(records):
    sorted_records = sorted(records, key=lambda r: (r[1], -r[2], r[0]))
    return [r[0] for r in sorted_records]

def caesar_shift(s, shift):
    result = []
    for ch in s:
        if ch.isalpha():
            base = ord('A') if ch.isupper() else ord('a')
            new_ch = chr((ord(ch) - base + shift) % 26 + base)
            result.append(new_ch)
        else:
            result.append(ch)
    return ''.join(result)

def rot13(s):
    result = []
    for ch in s:
        if ch.isalpha():
            base = ord('A') if ch.isupper() else ord('a')
            new_ch = chr((ord(ch) - base + 13) % 26 + base)
            result.append(new_ch)
        else:
            result.append(ch)
    return ''.join(result)

def atbash_cipher(s):
    result = []
    for ch in s:
        if ch.isalpha():
            if ch.isupper():
                new_ch = chr(ord('Z') - (ord(ch) - ord('A')))
            else:
                new_ch = chr(ord('z') - (ord(ch) - ord('a')))
            result.append(new_ch)
        else:
            result.append(ch)
    return ''.join(result)

def shortest_word(s):
    words = s.split()
    if not words:
        return ''
    shortest = words[0]
    for w in words[1:]:
        if len(w) < len(shortest):
            shortest = w
    return shortest

def reverse_word_order(s):
    words = s.split()
    return ' '.join(reversed(words))

def compress_consecutive_duplicates(s):
    if not s:
        return ''
    result = [s[0]]
    for ch in s[1:]:
        if ch != result[-1]:
            result.append(ch)
    return ''.join(result)

def remove_duplicate_letters_keep_first(s):
    seen = set()
    result = []
    for ch in s:
        if ch not in seen:
            seen.add(ch)
            result.append(ch)
    return ''.join(result)

def group_anagrams(words):
    groups = {}
    order = []
    for w in words:
        key = ''.join(sorted(w))
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(w)
    return [groups[key] for key in order]
